// AOS.init();

/* ===== Burger toggle ===== */
const burger = document.getElementById("burger");
const navList = document.getElementById("nav-list");
burger.addEventListener("click", () => navList.classList.toggle("show"));

/* ===== Dynamic year ===== */
document.getElementById("year").textContent = new Date().getFullYear();

const projects = [
    {
        title: "Portfolio V5",
        desc: "React + Tailwind personal site.",
        img: "https://placehold.co/600x350?text=Portfolio",
        demo: "https://eki.my.id",
        repo: "https://github.com/EkiZR/Portofolio_V5",
    },
    {
        title: "Todo App",
        desc: "Minimal todo tracker with local-storage.",
        img: "https://placehold.co/600x350?text=Todo+App",
        demo: "#",
        repo: "#",
    },
    {
        title: "Weather Widget",
        desc: "Live weather fetch using OpenWeather API.",
        img: "https://placehold.co/600x350?text=Weather",
        demo: "#",
        repo: "#",
    },
];

const certificates = [
    "https://placehold.co/600x400?text=Certificate+1",
    "https://placehold.co/600x400?text=Certificate+2",
    "https://placehold.co/600x400?text=Certificate+3",
];

const grid = document.getElementById("project-grid");
projects.forEach((p) => {
    const card = document.createElement("article");
    card.className = "project-card fade";
    card.innerHTML = `
    <img src="${p.img}" alt="${p.title}">
    <div class="content">
      <h4>${p.title}</h4>
      <p>${p.desc}</p>
      <div class="card-links">
        <a href="${p.demo}" target="_blank"><i class="fa fa-eye"></i> Live</a>
        <a href="${p.repo}" target="_blank"><i class="fa fa-code"></i> Code</a>
      </div>
    </div>`;
    grid.appendChild(card);
});

let start = document.querySelector('.loginClick')
start.addEventListener('click', () => {
    console.log('hello');
})
